<?php
$error=null;$edit=null;
if(request_method('POST')){try{verify_csrf();$action=post_string('action');if(in_array($action,['create','update'],true)){$name=post_string('department_name');$code=strtoupper(post_string('department_code'));$description=post_string('description');$status=post_string('status','Active');if(!in_array($status,['Active','Inactive'],true))throw new RuntimeException('Invalid department status.');if(!preg_match('/^[A-Z0-9-]{2,20}$/',$code))throw new RuntimeException('Department code must be 2–20 letters, numbers or hyphens.');if($name===''||$code==='')throw new RuntimeException('Department code and name are required.');if($action==='create'){$stmt=db()->prepare('INSERT INTO departments (department_code,department_name,description,status) VALUES (?,?,?,?)');$stmt->execute([$code,$name,nullable($description),$status]);$id=(int)db()->lastInsertId();log_action('CREATE','departments',$id,null,$_POST);flash('department','Department created.','success');}else{$id=(int)($_POST['department_id']??0);$old=db()->prepare('SELECT * FROM departments WHERE department_id=?');$old->execute([$id]);$before=$old->fetch();db()->prepare('UPDATE departments SET department_code=?,department_name=?,description=?,status=? WHERE department_id=?')->execute([$code,$name,nullable($description),$status,$id]);log_action('UPDATE','departments',$id,$before,$_POST);flash('department','Department updated.','success');}redirect_to('departments');}if($action==='toggle'){$id=(int)($_POST['department_id']??0);db()->prepare("UPDATE departments SET status=IF(status='Active','Inactive','Active') WHERE department_id=?")->execute([$id]);log_action('TOGGLE_STATUS','departments',$id);flash('department','Department status changed.','success');redirect_to('departments');}}catch(Throwable $e){$error=$e->getMessage();}}
if(isset($_GET['edit'])){$stmt=db()->prepare('SELECT * FROM departments WHERE department_id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}
$rows=db()->query("SELECT d.*,(SELECT COUNT(*) FROM doctors doc WHERE doc.department_id=d.department_id) doctor_count FROM departments d ORDER BY d.department_name")->fetchAll();
?>
<div class="page-header"><div><h2>Departments</h2><p>Organize doctors and services by clinical department.</p></div><div class="actions"><button class="btn btn-primary" data-modal-open="departmentModal">＋ Add department</button></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card"><div class="card-header"><div><h3>Department directory</h3><p><?=count($rows)?> configured departments.</p></div><input class="input" style="max-width:250px" placeholder="Search..." data-table-filter="departmentsTable"></div><div class="table-wrap"><table class="data-table" id="departmentsTable"><thead><tr><th>Code</th><th>Department</th><th>Description</th><th>Doctors</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="table-title"><?=e($r['department_code'])?></td><td><?=e($r['department_name'])?></td><td><?=e($r['description']??'—')?></td><td><?=e($r['doctor_count'])?></td><td><span class="badge badge-<?=status_class($r['status'])?>"><?=e($r['status'])?></span></td><td><div class="actions"><a class="btn btn-light btn-sm" href="<?=e(route_url('departments',['edit'=>$r['department_id']]))?>">Edit</a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="department_id" value="<?=$r['department_id']?>"><button class="btn btn-warning btn-sm" type="submit"><?= $r['status']==='Active'?'Disable':'Enable'?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="modal-backdrop <?=($edit||isset($_GET['new']))?'open':''?>" id="departmentModal"><div class="modal"><div class="modal-header"><h3><?=$edit?'Edit department':'Add department'?></h3><button class="close-btn" data-modal-close type="button">×</button></div><form method="post"><div class="modal-body"><?=csrf_field()?><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="department_id" value="<?=$edit['department_id']?>"><?php endif;?><div class="form-grid"><div class="field"><label class="required">Code</label><input class="input" name="department_code" value="<?=e($edit['department_code']??'')?>" required></div><div class="field"><label class="required">Name</label><input class="input" name="department_name" value="<?=e($edit['department_name']??'')?>" required></div></div><div class="field"><label>Description</label><textarea class="textarea" name="description"><?=e($edit['description']??'')?></textarea></div><div class="field"><label>Status</label><select class="select" name="status"><?php foreach(['Active','Inactive'] as $s):?><option <?=($edit['status']??'Active')===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div></div><div class="modal-footer"><a class="btn btn-light" href="<?=e(route_url('departments'))?>">Cancel</a><button class="btn btn-primary" type="submit">Save department</button></div></form></div></div>
